"""
    Where a string starts and ends with a quote, remove the quote
    """
def remove_quotes(s: Any) -> object {
    if ((len(s) > 1) and (s[0] == s[-1]) and (s[0] in ['"', "'"])) {
        return s[1:-1];
    }
    return s;
}

test_blocks:
test "t0" {
    assert (remove_quotes("hello\"") == "hello\"");;
}

test "t1" {
    assert (remove_quotes('"hello') == '"hello');;
}

test "t2" {
    assert (
        remove_quotes(
            """This is a string with quotes that spans multiple lines.
It includes a "quote character" that needs to be removed."""
        )
        == """This is a string with quotes that spans multiple lines.
It includes a "quote character" that needs to be removed."""
    );;
}

test "t3" {
    assert (remove_quotes("hello'") == "hello'");;
}

test "t4" {
    assert (
        remove_quotes("This is a string without quotes.")
        == "This is a string without quotes."
    );;
}

test "t5" {
    assert (remove_quotes("") == "");;
}

test "t6" {
    assert (remove_quotes('"hello"') == "hello");;
}

test "t7" {
    assert (remove_quotes("'hello'") == "hello");;
}

test "t8" {
    assert (remove_quotes("''") == "");;
}

test "t9" {
    assert (remove_quotes(remove_quotes("'spam'")) == 'spam');;
}

test "t10" {
    assert (remove_quotes(remove_quotes('spam')) == 'spam');;
}

test "t11" {
    assert (
        remove_quotes(
            """This is a string with quotes that spans multiple lines.
It includes a 'quote character' that needs to be removed."""
        )
        == """This is a string with quotes that spans multiple lines.
It includes a 'quote character' that needs to be removed."""
    );;
}

test "t12" {
    assert (remove_quotes(remove_quotes('"spam"')) == 'spam');;
}

test "t13" {
    assert (remove_quotes("hello") == "hello");;
}

test "t14" {
    assert (
        remove_quotes('"This is a string with quotes."')
        == "This is a string with quotes."
    );;
}

test "t15" {
    assert (
        remove_quotes("'This is a string with quotes.'")
        == "This is a string with quotes."
    );;
}

test "t16" {
    assert (remove_quotes("'hello") == "'hello");;
}
